    - {type_not_in: [TRANSLATION], table: {table: rdp, index: pc_sig, cmp: gt, threshold: 37}, table_exceeds_victim: {table: rdp, index: pc_sig, div: 4}, hit_rate_low: {table: hit_table, index: pc_sig, threshold: 4}}

